// Normalise one HubSpot delivery. The batch stays a batch: GTMOS's idempotency key for an array payload
// is `hubspot:batch:<sorted member eventIds>`, so splitting it into items here would destroy the very
// dedupe this workflow exists to demonstrate.
const first = $input.first().json;
const raw = Array.isArray(first.body) ? first.body : (Array.isArray(first) ? first : [first.body ?? first]);
if (!Array.isArray(raw) || raw.length === 0) {
  throw new Error('expected a non-empty JSON array of HubSpot change events');
}
const WANTED = new Set([
  'company.creation', 'company.deletion', 'company.propertyChange',
  'contact.creation', 'contact.deletion', 'contact.propertyChange',
  'deal.creation', 'deal.deletion', 'deal.propertyChange'
]);
const events = raw
  .filter((e) => e && typeof e === 'object')
  // `eventId` is the dedupe anchor. An event without one would silently push the whole batch onto the
  // body-hash fallback, so it is dropped rather than allowed to poison the key.
  .filter((e) => e.eventId !== undefined && e.eventId !== null && String(e.eventId) !== '')
  .filter((e) => !e.subscriptionType || WANTED.has(e.subscriptionType))
  .map((e) => ({
    eventId: e.eventId,
    subscriptionType: e.subscriptionType ?? 'company.propertyChange',
    objectId: e.objectId ?? null,
    propertyName: e.propertyName ?? null,
    propertyValue: e.propertyValue ?? null,
    occurredAt: e.occurredAt ?? null,
    portalId: e.portalId ?? null,
    changeSource: e.changeSource ?? null,
    // Forwarded on purpose. It is the field that differs between attempts, and GTMOS strips it before
    // hashing — passing it through is what makes the dedupe test honest rather than staged.
    attemptNumber: e.attemptNumber ?? 0
  }));
if (events.length === 0) {
  throw new Error('no usable HubSpot events in payload (need objects carrying eventId)');
}
const eventIds = events.map((e) => String(e.eventId));
try {
  $execution.customData.set('gtmos_hubspot_event_ids', eventIds.join(',').slice(0, 250));
  $execution.customData.set('gtmos_hubspot_attempt', String(events[0].attemptNumber));
} catch (e) { /* telemetry must not break ingestion */ }
return [{ json: { events, batch_size: events.length, event_ids: eventIds, dropped: raw.length - events.length } }];

// GTMOS verifies inbound CRM webhooks with HubSpot's own v3 scheme:
//   base64(HMAC-SHA256(client_secret, METHOD + uri + rawBody + timestamp_ms))
// It signs the *raw body bytes* and the URI exactly as received, so the body string built here is the
// one the HTTP node sends verbatim (contentType: raw) — re-serialising it downstream would break the MAC.
// With no client secret configured, GTMOS reports signature_status `not_configured` and accepts the
// delivery in development; this node then sends empty signature headers rather than a forged one.
const crypto = require('crypto');
const url = ($env.GTMOS_BASE_URL ?? '') + '/api/v1/webhooks/hubspot';
const body = JSON.stringify($input.first().json.events);
const ts = Date.now().toString();
const secret = $env.HUBSPOT_WEBHOOK_CLIENT_SECRET ?? '';
const sig = secret
  ? crypto.createHmac('sha256', secret).update('POST' + url + body + ts).digest('base64')
  : '';
return [{ json: { url, body, ts, sig, signed: Boolean(secret) } }];

const res = $input.first().json;
const b = res.body ?? {};
const batch = $('Normalise HubSpot batch').first().json;
const out = {
  forwarded: batch.batch_size,
  dropped: batch.dropped,
  event_ids: batch.event_ids,
  attempt_number: batch.events[0].attemptNumber,
  http_status: res.statusCode ?? null,
  gtmos_event_id: b.id ?? null,
  status: b.status ?? null,
  duplicate: b.duplicate === true,
  signature: b.signature ?? null,
  correlation_id: b.correlation_id ?? null,
  error: b.error ?? null
};
try { $execution.customData.set('gtmos_duplicate', String(out.duplicate)); } catch (e) { /* noop */ }
return [{ json: out }];
